// Parse the LLM's JSON response defensively -- LLMs occasionally wrap
// JSON in markdown code fences despite instructions not to, so strip
// those before parsing rather than letting the workflow fail on it.
const raw = $input.first().json.content?.[0]?.text || $input.first().json.text || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { category: 'uncategorized', reasoning: 'LLM response was not valid JSON: ' + cleaned.slice(0, 200) };
}
return [{ json: {
  person_id: $('Get Person Skills').first().json.person_id,
  category: parsed.category,
  reasoning: parsed.reasoning
} }];
